22	export const runScenario = (scenario: Scenario): Result[] => {
23	  let previousContracts = 0;
24	  return scenario.steps.map((step) => {
25	    const premium = quote(
26	      {
27	        yearsWithMHPCO: scenario.customer.yearsWithMHPCO,
28	        previousContracts,
29	      },
30	      step.items ?? [],
31	    );
32	    previousContracts += 1;
33	    return { premium };
34	  });
35	};
