import type { Item } from "./claim-office.js";
import { quote } from "./claim-office.js";

// A scenario is the parsed input format: a customer and a list of steps to run
// against them. It is deliberately separate from the CLI itself — reading stdin
// and writing stdout are I/O concerns, while running a scenario is not, and
// keeping them apart lets the step logic be tested without a process.

// The scenario names a customer by years alone. Previous contracts are not
// given: they are derived from the customer's position in the scenario, since
// each quote step is itself a contract.
export type ScenarioCustomer = {
  yearsWithMHPCO: number;
};

export type Step = {
  op: string;
  items?: Item[];
};

export type Scenario = {
  customer: ScenarioCustomer;
  steps: Step[];
};

export type StepResult = {
  premium?: number;
};

// Each quote step signs one contract, so by the time step n runs the customer
// already holds n contracts. That makes "previous contracts" the step's own
// index rather than a running total that has to be kept in step by hand.
const previousContractsAt = (stepIndex: number): number => stepIndex;

const runStep = (
  customer: ScenarioCustomer,
  step: Step,
  stepIndex: number,
): StepResult => ({
  premium: quote(
    {
      yearsWithMHPCO: customer.yearsWithMHPCO,
      previousContracts: previousContractsAt(stepIndex),
    },
    step.items ?? [],
  ),
});

export const runScenario = (scenario: Scenario): StepResult[] =>
  scenario.steps.map((step, stepIndex) =>
    runStep(scenario.customer, step, stepIndex),
  );

